"""Render docs/indicator_values.md from the indicator tables (all values computed, none typed)."""
from pathlib import Path

import duckdb

ROOT = Path(__file__).resolve().parents[1]
G = ROOT / "data/gold/parquet"
q = lambda sql: duckdb.sql(sql.replace("@", G.as_posix() + "/")).df()
pct = lambda s: s.map(lambda v: "" if v != v else f"{v*100:.1f}%")
out = ["# Indicator values (generated)\n",
       "Generated by `analysis/render_indicator_values.py` from the gold indicator tables. "
       "FY2027 is partial (contracts signed to 31 Oct 2026).\n"]

s = q("SELECT * FROM '@ind_summary_by_fy.parquet' ORDER BY fiscal_year")
t = s[["fiscal_year"]].copy()
t["FY complete"] = s.is_complete_fy.map({True: "yes", False: "partial"})
t["I1 value (USD bn)"] = (s.total_award_value_usd.astype(float) / 1e9).map("{:,.2f}".format)
t["I2 contracts"] = s.contract_count.map("{:,}".format)
t["I3 avg (USD k)"] = (s.avg_contract_value_usd.astype(float) / 1e3).map("{:,.0f}".format)
t["I3 median (USD k)"] = (s.median_contract_value_usd.astype(float) / 1e3).map("{:,.1f}".format)
t["I5 open comp."] = pct(s.open_competitive_value_share.astype(float))
t["I6 direct (value)"] = pct(s.direct_selection_value_share.astype(float))
t["I6 direct (count)"] = pct(s.direct_selection_count_share.astype(float))
t["I7 domestic"] = pct(s.domestic_supplier_value_share.astype(float))
t["I9 prior review"] = pct(s.prior_review_value_share.astype(float))
out += ["## Scalar indicators by fiscal year\n", t.to_markdown(index=False), ""]

c = q("SELECT * FROM '@ind_supplier_concentration.parquet' ORDER BY fiscal_year")
c2 = c[["fiscal_year"]].copy()
c2["firms"] = c.supplier_count.map("{:,}".format)
c2["I8 top-10 share"] = pct(c.top10_supplier_value_share.astype(float))
c2["top-100 share"] = pct(c.top100_supplier_value_share.astype(float))
c2["HHI"] = c.hhi.astype(float).map("{:,.1f}".format)
out += ["## I8 Supplier concentration (firms only)\n", c2.to_markdown(index=False), ""]

m = q("""SELECT competition_tier, fiscal_year, SUM(value_share) s FROM '@ind_method_mix.parquet' GROUP BY 1, 2""")
mp = m.pivot(index="competition_tier", columns="fiscal_year", values="s").fillna(0)
mp = mp.apply(lambda col: col.map(lambda v: f"{v*100:.1f}%"))
mp.columns = [f"FY{c}" for c in mp.columns]
out += ["## I4 Method mix: share of award value by competition tier\n", mp.reset_index().to_markdown(index=False), ""]

r = q("""SELECT region_name, SUM(value_usd) v FROM '@ind_region.parquet' r
         JOIN '@dim_fiscal_year.parquet' y USING (fiscal_year) WHERE y.is_complete_fy GROUP BY 1 ORDER BY v DESC""")
r["share"] = pct(r.v / r.v.sum())
r["value (USD bn)"] = (r.v.astype(float) / 1e9).map("{:,.2f}".format)
out += ["## I10 Award value by region, FY2020–FY2026\n", r[["region_name", "value (USD bn)", "share"]].to_markdown(index=False), ""]

se = q("""SELECT global_practice, SUM(allocated_value_usd) v FROM '@ind_sector.parquet' x
          JOIN '@dim_fiscal_year.parquet' y USING (fiscal_year) WHERE y.is_complete_fy GROUP BY 1 ORDER BY v DESC""")
se["share"] = pct(se.v / se.v.sum())
se["allocated value (USD bn)"] = (se.v.astype(float) / 1e9).map("{:,.2f}".format)
out += ["## I10 Award value by global practice (equal-split allocation), FY2020–FY2026\n",
        se[["global_practice", "allocated value (USD bn)", "share"]].to_markdown(index=False), ""]

(ROOT / "docs/indicator_values.md").write_text("\n".join(out) + "\n")
print("\n".join(out))
